CREATE FUNCTION public.owns_customer_booking(_booking uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS (SELECT 1 FROM public.bookings b WHERE b.id=_booking AND (b.user_id=auth.uid() OR (lower(b.email)=lower(auth.jwt()->>'email') AND (auth.jwt()->>'email_verified')::boolean IS DISTINCT FROM false))); $$;
REVOKE ALL ON FUNCTION public.owns_customer_booking(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.owns_customer_booking(uuid) TO authenticated;
CREATE TABLE public.booking_disputes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES public.bookings(id), customer_id uuid NOT NULL REFERENCES public.profiles(id), kind text NOT NULL CHECK(kind IN ('unpaid','uncleaned')), details text NOT NULL CHECK(char_length(details) BETWEEN 10 AND 2000), status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','reviewing','resolved','dismissed')), resolution text NOT NULL DEFAULT '', resolved_by uuid REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(booking_id,kind));
GRANT SELECT ON public.booking_disputes TO authenticated;
GRANT ALL ON public.booking_disputes TO service_role;
ALTER TABLE public.booking_disputes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Customer own disputes or admin" ON public.booking_disputes FOR SELECT TO authenticated USING(customer_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.submit_booking_dispute(_booking uuid,_kind text,_details text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF NOT public.owns_customer_booking(_booking) THEN RAISE EXCEPTION 'Only the customer can report this booking'; END IF; IF _kind NOT IN ('unpaid','uncleaned') OR char_length(trim(_details)) NOT BETWEEN 10 AND 2000 THEN RAISE EXCEPTION 'Choose a reason and enter 10 to 2000 characters'; END IF; INSERT INTO public.booking_disputes(booking_id,customer_id,kind,details) VALUES(_booking,auth.uid(),_kind,trim(_details)) RETURNING id INTO result; RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.submit_booking_dispute(uuid,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_booking_dispute(uuid,text,text) TO authenticated;
CREATE FUNCTION public.resolve_booking_dispute(_id uuid,_status text,_resolution text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin access required'; END IF; IF _status NOT IN ('open','reviewing','resolved','dismissed') OR char_length(trim(_resolution))>2000 OR (_status IN ('resolved','dismissed') AND char_length(trim(_resolution))<3) THEN RAISE EXCEPTION 'Final decisions require a resolution note'; END IF; UPDATE public.booking_disputes SET status=_status,resolution=trim(_resolution),resolved_by=auth.uid(),updated_at=now() WHERE id=_id; IF NOT FOUND THEN RAISE EXCEPTION 'Dispute not found'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.resolve_booking_dispute(uuid,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.resolve_booking_dispute(uuid,text,text) TO authenticated;
CREATE TABLE public.cleaner_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL UNIQUE REFERENCES public.bookings(id), customer_id uuid NOT NULL REFERENCES public.profiles(id), cleaner_id uuid NOT NULL REFERENCES public.profiles(id), rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5), body text NOT NULL CHECK(char_length(body) BETWEEN 10 AND 2000), public_name text NOT NULL DEFAULT 'Verified customer' CHECK(char_length(public_name) BETWEEN 1 AND 60), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.cleaner_reviews TO authenticated;
GRANT ALL ON public.cleaner_reviews TO service_role;
ALTER TABLE public.cleaner_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Customer own reviews or admin" ON public.cleaner_reviews FOR SELECT TO authenticated USING(customer_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.submit_cleaner_review(_booking uuid,_rating integer,_body text,_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.bookings; result uuid; BEGIN IF NOT public.owns_customer_booking(_booking) THEN RAISE EXCEPTION 'Only the customer can review this booking'; END IF; SELECT * INTO b FROM public.bookings WHERE id=_booking FOR UPDATE; IF b.status<>'completed' OR b.cleaner_id IS NULL THEN RAISE EXCEPTION 'Reviews open after an assigned cleaning is completed'; END IF; IF _rating NOT BETWEEN 1 AND 5 OR char_length(trim(_body)) NOT BETWEEN 10 AND 2000 OR char_length(trim(_name)) NOT BETWEEN 1 AND 60 THEN RAISE EXCEPTION 'Enter a rating, review and public display name'; END IF; INSERT INTO public.cleaner_reviews(booking_id,customer_id,cleaner_id,rating,body,public_name) VALUES(b.id,auth.uid(),b.cleaner_id,_rating,trim(_body),trim(_name)) RETURNING id INTO result; RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.submit_cleaner_review(uuid,integer,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_cleaner_review(uuid,integer,text,text) TO authenticated;
CREATE FUNCTION public.public_cleaner_reviews(_cleaner uuid) RETURNS TABLE(id uuid,rating integer,body text,public_name text,created_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT r.id,r.rating,r.body,r.public_name,r.created_at FROM public.cleaner_reviews r JOIN public.housekeeper_portfolios p ON p.user_id=r.cleaner_id WHERE r.cleaner_id=_cleaner AND p.published AND public.has_role(p.user_id,'cleaner') ORDER BY r.created_at DESC LIMIT 100; $$;
REVOKE ALL ON FUNCTION public.public_cleaner_reviews(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.public_cleaner_reviews(uuid) TO anon,authenticated;
